SELECT ?z ?ztype ?label WHERE {
  ?z rdfs:label ?label .
  FILTER (CONTAINS(?label, "ZN_6"))
  OPTIONAL { ?z a ?ztype }
}

SELECT ?p ?pc ?tsid ?label WHERE {
  ?p brick:hasLocation ?z .
  ?z a brick:HVAC_Zone .
  ?z rdfs:label "DataCenter_bot_ZN_6" .
  ?p a ?pc .
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid }
  OPTIONAL { ?p rdfs:label ?label }
}

SELECT ?p ?pc ?tsid ?label ?rel WHERE {
  ?z a brick:HVAC_Zone .
  ?z rdfs:label "DataCenter_bot_ZN_6" .
  ?p a ?pc .
  { ?p brick:hasLocation ?z } UNION { ?p brick:inLocation ?z } UNION { ?z brick:hasPointOf ?p } UNION { ?p brick:about ?z }
  OPTIONAL { ?p ref:hasTimeseriesId ?tsid }
  OPTIONAL { ?p rdfs:label ?label }
}

